def build_order(jobs: list[Job]) -> Result[list[str], str]:
    job_map = {}
    for job in jobs:
        if job.name in job_map:
            return Err(f"duplicate job: {job.name}")
        job_map[job.name] = job

    for job in jobs:
        for dep in job.deps:
            if dep not in job_map:
                return Err(f"unknown dependency: {dep}")

    order = []
    while jobs:
        available = [job for job in jobs if all(dep in order for dep in job.deps)]
        if not available:
            return Err("cycle detected")
        job = available[0]
        order.append(job.name)
        jobs.remove(job)

    return Ok(order)

