def k_most_frequent(xs: list[int], k: int) -> list[tuple[int, int]]:
    if k <= 0:
        return []

    count_map = {}
    for x in xs:
        if x in count_map:
            count_map[x] += 1
        else:
            count_map[x] = 1

    sorted_counts = sorted(count_map.items(), key=lambda item: (-item[1], item[0]))
    return sorted_counts[:k]

