class Line:
    sku: str
    qty: int
    unit_cents: int

def invoice_total(lines: list[Line], coupon: str) -> Result[int, str]:
    if any(line.qty < 1 for line in lines):
        return Err(f"bad quantity: {lines[next(i for i, line in enumerate(lines) if line.qty < 1)].sku}")

    subtotal = sum(line.qty * line.unit_cents - (line.qty * line.unit_cents // 10 if line.qty >= 10 else 0) for line in lines)

    if coupon == "SAVE500":
        subtotal = max(subtotal - 500, 0)
    elif coupon == "PCT10":
        subtotal -= subtotal // 10
    elif coupon == "BIG20":
        if subtotal >= 10000:
            subtotal -= subtotal // 5
        else:
            return Err(f"coupon not applicable: {coupon}")
    elif coupon != "":
        return Err(f"unknown coupon: {coupon}")

    tax = (subtotal * 8 + 50) // 100
    return Ok(subtotal + tax)

