def max_subarray(xs: list[int]) -> Option[tuple[int, int, int]]:
    if len(xs) == 0:
        return None
    max_sum = xs[0]
    start = 0
    end = 0
    current_sum = xs[0]
    current_start = 0
    for i in range(1, len(xs)):
        if xs[i] > current_sum + xs[i]:
            current_sum = xs[i]
            current_start = i
        else:
            current_sum += xs[i]
        if current_sum > max_sum:
            max_sum = current_sum
            start = current_start
            end = i
    return Some((max_sum, start, end))

